<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue';
import { Head, Link, usePage } from '@inertiajs/vue3';

const page = usePage();
const theme = ref('dark');
const activeJourney = ref(0);
const activeMode = ref(0);
const revealedSections = ref(new Set());
const navOpen = ref(false);
const journeyTabs = ref([]);
const modeTabs = ref([]);
let observer;
const isAuthenticated = computed(() => !!page.props.auth?.user);
const ctaText = computed(() => isAuthenticated.value ? 'Masuk Dashboard' : 'Masuk ke Platform');
const ctaHref = computed(() => isAuthenticated.value ? '/dashboard' : '/login');
const journey = [
    { label: 'ASSESS', title: 'Mulai dari baseline yang jujur', text: 'Pretest memetakan pengetahuan awal tanpa asumsi.', metric: 'Pretest', value: '54', accent: 'brand' },
    { label: 'LEARN', title: 'Belajar dalam konteks nyata', text: 'Modul singkat membantu tim memahami keputusan yang tepat.', metric: 'Progress', value: '68%', accent: 'ok' },
    { label: 'PRACTICE', title: 'Uji respons sebelum insiden', text: 'Case study dan CTF mengubah teori menjadi kebiasaan.', metric: 'Scenario', value: '12', accent: 'warn' },
    { label: 'SIMULATE', title: 'Simulasikan tekanan sebenarnya', text: 'Phishing dan tabletop melatih koordinasi lintas peran.', metric: 'Response', value: '82%', accent: 'danger' },
    { label: 'MEASURE', title: 'Lihat kesiapan secara menyeluruh', text: 'Reporting menghubungkan aktivitas dengan learning gain.', metric: 'Readiness', value: '82', accent: 'brand' },
];
const learningModes = [
    { label: 'TRAIN', title: 'Bangun pemahaman yang melekat', text: 'Awareness Training dan Assessment membuat baseline relevan dengan pekerjaan sehari-hari.', type: 'module', stat: '8 / 10', statLabel: 'modul selesai', detail: 'Awareness Training · Assessment' },
    { label: 'DECIDE', title: 'Latih keputusan, bukan hafalan', text: 'Case Studies bercabang menunjukkan konsekuensi dari setiap pilihan sebelum menjadi insiden.', type: 'decision', stat: 'B', statLabel: 'pilihan saat ini', detail: 'Case Studies' },
    { label: 'PRACTICE', title: 'Berlatih di ruang yang aman', text: 'CTF / Security Lab dan Phishing Simulation memberi ruang untuk mencoba, gagal, lalu memperbaiki.', type: 'challenge', stat: '03:42', statLabel: 'waktu tersisa', detail: 'CTF / Security Lab · Phishing Simulation' },
    { label: 'RESPOND', title: 'Respons sebagai satu tim', text: 'Tabletop Exercise menyatukan peran, komunikasi, dan keputusan ketika tekanan meningkat.', type: 'tabletop', stat: '4 / 4', statLabel: 'fase aktif', detail: 'Tabletop Exercise' },
];
const currentJourney = computed(() => journey[activeJourney.value]);
const currentMode = computed(() => learningModes[activeMode.value]);
const scrollTo = (id) => { navOpen.value = false; document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' }); };
const handleKeydown = (event) => { if (event.key === 'Escape' && navOpen.value) navOpen.value = false; };
const toggleTheme = () => { theme.value = theme.value === 'dark' ? 'light' : 'dark'; document.documentElement.dataset.theme = theme.value; localStorage.setItem('theme', theme.value); };
const selectJourney = (index) => { activeJourney.value = index; nextTick(() => journeyTabs.value[index]?.focus()); };
const selectMode = (index) => { activeMode.value = index; nextTick(() => modeTabs.value[index]?.focus()); };
const moveJourney = (event, direction) => { event.preventDefault(); selectJourney((activeJourney.value + direction + journey.length) % journey.length); };
const moveMode = (event, direction) => { event.preventDefault(); selectMode((activeMode.value + direction + learningModes.length) % learningModes.length); };
onMounted(() => {
    document.addEventListener('keydown', handleKeydown);
    const saved = localStorage.getItem('theme') || 'dark';
    theme.value = saved;
    document.documentElement.dataset.theme = saved;
    observer = new IntersectionObserver((entries) => entries.forEach((entry) => {
        if (entry.isIntersecting) revealedSections.value = new Set([...revealedSections.value, entry.target.id]);
    }), { threshold: 0.12 });
    document.querySelectorAll('[data-reveal]').forEach((section) => observer.observe(section));
});
onUnmounted(() => { observer?.disconnect(); document.removeEventListener('keydown', handleKeydown); });
</script>

